'use strict';
const {JSDOM}=require('jsdom'),assert=require('node:assert/strict'),vm=require('node:vm'),fs=require('node:fs'),{webcrypto,createHash}=require('node:crypto'),{gzipSync}=require('node:zlib');
const input=JSON.parse(fs.readFileSync(0,'utf8')),hash=s=>createHash('sha256').update(s).digest('hex'),pause=()=>new Promise(r=>setImmediate(r));
function fixture(options={}){
 const dom=new JSDOM('',{url:'http://localhost/book/index.html'}),calls=[],config=JSON.parse(JSON.stringify(input.config)),pending=[],state={decompressions:0};if(options.protocol==='old')delete config.sharedFrame.wrapperDelivery;
 const card={id:'A',url:'cards/A.html'},gzipPath='evidence/_study_prepared_wrapper_'+input.full.source_wrapper_sha256+'.html.gz';
 const scope={config,location:{href:'http://localhost/book/index.html'},URL,DOMParser:dom.window.DOMParser,crypto:webcrypto,TextEncoder,TextDecoder,AbortController,DOMException,Response,console,cardCache:new Map(),cardRequests:new Map(),activeCardRequest:null,backgroundCardRequest:null,cardCacheBytes:0,cacheLimit:4,cacheByteLimit:16*1024*1024,prefetchByteLimit:2*1024*1024};
 scope.DecompressionStream=options.noDS?undefined:class{constructor(format){state.decompressions++;return new DecompressionStream(format)}};
 scope.safeURL=value=>new URL(value,scope.location.href).href;
 scope.fetch=async(url,settings={})=>{const path=new URL(url).pathname.replace('/book/','');calls.push(path);if(path==='prepared-index.json')return new Response(input.index);if(path==='full.json'){if(options.holdFull)return new Promise(resolve=>pending.push(()=>resolve(new Response(input.fullText))));return new Response(input.fullText)}if(path===card.url)return new Response(input.wrapper);if(path===gzipPath){if(options.abort){options.abort.abort(new DOMException('cancelled source','AbortError'));throw Error('transport cancelled')}if(options.abortDuringDecode)return new Response(new ReadableStream({pull(controller){state.decodedReads=(state.decodedReads||0)+1;controller.enqueue(new TextEncoder().encode('decoded source prefix'));options.abortDuringDecode.abort(new DOMException('cancelled decoded stream','AbortError'));controller.close()}},{highWaterMark:0}),{headers:{'Content-Encoding':'gzip'}});if(options.gzip==='missing')return new Response('',{status:404});if(options.gzip==='bad')return new Response('not a gzip stream');const text=options.gzip==='tampered'?input.wrapper.replaceAll('完整','篡改'):options.decoded||input.wrapper;if(options.encoded)return new Response(text,{headers:{'Content-Encoding':'gzip'}});return new Response(gzipSync(Buffer.from(text)))}throw Error('unexpected source request '+path)};
 vm.createContext(scope);vm.runInContext(input.parsers+'\n'+input.delivery+'\nglobalThis.api={fetchCard,authoredWrapperText,cacheCard,preparedCard};',scope);
 const binding={index_sha256:config.sharedFrame.preparedIndex.sha256,full_prepared_sha256:input.rule.sha256,source_wrapper_sha256:input.full.source_wrapper_sha256,wrapper_url:card.url,...options.binding};
 if(options.noIndex){config.sharedFrame.prepared=JSON.parse(input.index).cards;delete config.sharedFrame.preparedIndex;delete binding.index_sha256}
 if(options.cached!==false)scope.api.cacheCard(card.id,{frontOnly:true,deliveryBinding:binding},100);
 return{dom,scope,api:scope.api,card,gzipPath,calls,pending,state,close:()=>dom.window.close()};
}
(async()=>{let contracts=0;
let f=fixture();const loaded=await f.api.fetchCard(f.card);assert.equal(loaded.prepared.source_wrapper_sha256,input.full.source_wrapper_sha256);assert.equal(loaded.sides[0],input.sides[0]);assert.equal(f.calls.filter(p=>p===f.gzipPath).length,1);assert.equal(f.calls.includes(f.card.url),false);assert.equal(f.state.decompressions,1);contracts++;f.close();
for(const gzip of ['missing','bad']){f=fixture({gzip});assert.equal((await f.api.fetchCard(f.card)).sides[0],input.sides[0]);assert.equal(f.calls.filter(p=>p===f.card.url).length,1);contracts++;f.close()}
f=fixture({gzip:'tampered'});await assert.rejects(f.api.fetchCard(f.card),/Prepared card source wrapper differs/);assert.equal(f.calls.includes(f.card.url),false,'valid gzip with a wrong decoded source was silently replaced by raw bytes');contracts++;f.close();
for(const options of [{protocol:'old'},{noDS:true}]){f=fixture(options);assert.equal((await f.api.fetchCard(f.card)).sides[0],input.sides[0]);assert.equal(f.calls.includes(f.gzipPath),false);assert.equal(f.calls.includes(f.card.url),true);contracts++;f.close()}
f=fixture({encoded:true});assert.equal((await f.api.fetchCard(f.card)).sides[0],input.sides[0]);assert.equal(f.state.decompressions,0,'an automatically decoded HTTP gzip response was decompressed twice');contracts++;f.close();
const budget=2*1024*1024;f=fixture({decoded:'x'.repeat(budget+100)});await assert.rejects(f.api.authoredWrapperText(f.card,new AbortController().signal,budget,Promise.resolve(input.full)),e=>e.name==='StudyPrefetchLimit');assert.equal(f.calls.includes(f.card.url),false,'decoded streaming budget failure retried unbounded raw source');contracts++;f.close();
const abort=new AbortController();f=fixture({abort});await assert.rejects(f.api.authoredWrapperText(f.card,abort.signal,budget,Promise.resolve(input.full)),e=>e.name==='AbortError');assert.equal(f.calls.includes(f.card.url),false);contracts++;f.close();
const streamAbort=new AbortController();f=fixture({abortDuringDecode:streamAbort});await assert.rejects(f.api.authoredWrapperText(f.card,streamAbort.signal,budget,Promise.resolve(input.full)),e=>e.name==='AbortError');assert.equal(f.state.decodedReads,1);assert.equal(f.calls.includes(f.card.url),false);contracts++;f.close();
for(const binding of [{index_sha256:hash('stale index'),source_wrapper_sha256:hash('stale wrapper')},{full_prepared_sha256:hash('stale artifact'),source_wrapper_sha256:hash('stale wrapper')},{wrapper_url:'cards/different.html',source_wrapper_sha256:hash('stale wrapper')}]){f=fixture({binding,holdFull:true});const promise=f.api.fetchCard(f.card);for(let i=0;i<10&&!f.pending.length;i++)await pause();assert.equal(f.pending.length,1);assert.equal(f.calls.some(p=>p.endsWith('.html.gz')),false,'stale cached binding selected a source before the verified artifact');f.pending.shift()();await promise;assert.equal(f.calls.includes(f.gzipPath),true);assert.equal(f.calls.some(p=>p.includes(hash('stale wrapper'))),false);contracts++;f.close()}
f=fixture({noIndex:true,binding:{source_wrapper_sha256:hash('uncertified hint')}});assert.equal((await f.api.fetchCard(f.card)).sides[0],input.sides[0]);assert.equal(f.calls.some(p=>p.includes(hash('uncertified hint'))),false,'undefined index identities certified a stale hint');contracts++;f.close();
f=fixture({cached:false});assert.equal((await f.api.fetchCard(f.card)).sides[1],input.sides[1]);assert.equal(f.calls.includes(f.gzipPath),true);contracts++;f.close();
console.log(JSON.stringify({contracts,sourceBytesPreserved:true,wrongDecodedSourceRejected:true,decodedBudgetAndAbort:true,staleHintsRejected:true,pass:true}));})().catch(error=>{console.error(error);process.exitCode=1});
